ALTER TABLE xp_evidence_events ADD COLUMN gem_receipt_allowed_at_award INTEGER NOT NULL DEFAULT 1 CHECK (gem_receipt_allowed_at_award IN (0,1));
ALTER TABLE xp_level_unlocks ADD COLUMN gem_receipt_allowed INTEGER NOT NULL DEFAULT 1 CHECK (gem_receipt_allowed IN (0,1));
ALTER TABLE gem_xp_transition_receipts ADD COLUMN outcome TEXT NOT NULL DEFAULT 'APPLIED' CHECK (outcome IN ('APPLIED','DENIED'));
ALTER TABLE gem_xp_transition_receipts ADD COLUMN movement_id_new TEXT;
UPDATE gem_xp_transition_receipts SET movement_id_new = movement_id;
CREATE TABLE gem_xp_transition_receipts_new (transition_id TEXT PRIMARY KEY, sequence INTEGER NOT NULL UNIQUE, unlock_id TEXT NOT NULL REFERENCES xp_level_unlocks(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK(kind IN ('GRANT','REVOKE','REINSTATE')), source_event_id TEXT REFERENCES xp_evidence_events(id) ON DELETE RESTRICT, source_reversal_id TEXT REFERENCES xp_evidence_reversals(id) ON DELETE RESTRICT, movement_id TEXT UNIQUE REFERENCES gem_ledger(id) ON DELETE RESTRICT, outcome TEXT NOT NULL CHECK(outcome IN ('APPLIED','DENIED')), fingerprint TEXT NOT NULL, created_at TEXT NOT NULL, CHECK((outcome='APPLIED' AND movement_id IS NOT NULL) OR (outcome='DENIED' AND movement_id IS NULL)));
INSERT INTO gem_xp_transition_receipts_new (transition_id,sequence,unlock_id,kind,source_event_id,source_reversal_id,movement_id,outcome,fingerprint,created_at) SELECT transition_id,sequence,unlock_id,kind,source_event_id,source_reversal_id,movement_id_new,outcome,fingerprint,created_at FROM gem_xp_transition_receipts;
DROP TABLE gem_xp_transition_receipts;
ALTER TABLE gem_xp_transition_receipts_new RENAME TO gem_xp_transition_receipts;
CREATE UNIQUE INDEX uq_gem_xp_receipt_sequence ON gem_xp_transition_receipts(sequence);
ALTER TABLE rt_streak_emerald_entitlements ADD COLUMN gem_receipt_allowed INTEGER NOT NULL DEFAULT 1 CHECK (gem_receipt_allowed IN (0,1));
ALTER TABLE gem_reconciliation_revisions ADD COLUMN outcome TEXT NOT NULL DEFAULT 'APPLIED' CHECK (outcome IN ('APPLIED','NO_MOVEMENT','DENIED'));
ALTER TABLE real_class_sessions ADD COLUMN behaviour_snapshot_version INTEGER CHECK (behaviour_snapshot_version IS NULL OR behaviour_snapshot_version = 1);
CREATE TABLE behaviour_student_state (student_id TEXT NOT NULL, owner_teacher_id TEXT NOT NULL, academic_year_id TEXT NOT NULL, group_id TEXT NOT NULL, current_lives INTEGER NOT NULL DEFAULT 4 CHECK(current_lives BETWEEN 0 AND 4), last_effective_action_id TEXT, active_zero_source_action_id TEXT, PRIMARY KEY(student_id, academic_year_id), UNIQUE(student_id, owner_teacher_id, academic_year_id, group_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE RESTRICT, FOREIGN KEY(owner_teacher_id) REFERENCES teacher_accounts(id) ON DELETE RESTRICT, FOREIGN KEY(academic_year_id) REFERENCES academic_years(id) ON DELETE RESTRICT, FOREIGN KEY(group_id) REFERENCES groups(id) ON DELETE RESTRICT);
CREATE TABLE real_class_session_behaviour_roster (session_id TEXT NOT NULL, student_id TEXT NOT NULL, owner_teacher_id TEXT NOT NULL, academic_year_id TEXT NOT NULL, group_id TEXT NOT NULL, term_id TEXT NOT NULL, lives_at_start INTEGER NOT NULL CHECK(lives_at_start BETWEEN 0 AND 4), inherited_action_id TEXT, zero_source_action_id TEXT, PRIMARY KEY(session_id, student_id), FOREIGN KEY(session_id) REFERENCES real_class_sessions(id) ON DELETE RESTRICT, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE RESTRICT);
CREATE TABLE behaviour_actions (id TEXT PRIMARY KEY, owner_teacher_id TEXT NOT NULL, academic_year_id TEXT NOT NULL, group_id TEXT NOT NULL, session_id TEXT NOT NULL, student_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('LOSS','RESTORE','CORRECTION')), delta INTEGER NOT NULL, lineage TEXT NOT NULL, request_key TEXT NOT NULL, fingerprint TEXT NOT NULL, correction_of TEXT, created_at TEXT NOT NULL, FOREIGN KEY(session_id, student_id) REFERENCES real_class_session_behaviour_roster(session_id, student_id) ON DELETE RESTRICT, UNIQUE(owner_teacher_id, request_key));
CREATE TABLE behaviour_incidents (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, student_id TEXT NOT NULL, owner_teacher_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('ACTIVE','CORRECTED')), trigger_action_id TEXT NOT NULL, corrected_by_action_id TEXT, created_at TEXT NOT NULL, UNIQUE(session_id, student_id), FOREIGN KEY(session_id, student_id) REFERENCES real_class_session_behaviour_roster(session_id, student_id) ON DELETE RESTRICT);
CREATE TABLE behaviour_proposals (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, student_id TEXT NOT NULL, owner_teacher_id TEXT NOT NULL, zero_source_action_id TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('OPEN','DISMISSED','WITHDRAWN')), created_at TEXT NOT NULL, dismissed_at TEXT, FOREIGN KEY(session_id, student_id) REFERENCES real_class_session_behaviour_roster(session_id, student_id) ON DELETE RESTRICT);
CREATE TABLE behaviour_requests (id TEXT PRIMARY KEY, owner_teacher_id TEXT NOT NULL, request_key TEXT NOT NULL, operation TEXT NOT NULL, fingerprint TEXT NOT NULL, target_id TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(owner_teacher_id, request_key));
CREATE INDEX idx_behaviour_state_owner_group ON behaviour_student_state(owner_teacher_id, group_id, academic_year_id);
CREATE INDEX idx_behaviour_actions_session_student ON behaviour_actions(session_id, student_id, created_at, id);
